package org.diy.watchrecorder;
import android.content.*;import android.os.*;import java.util.*;import org.json.*;
/** On-watch threshold guard during user-enabled recording; no network or health inference. */
final class WatchContextReminder {
 private Float heart,light;private long heartAt,lightAt;
 void observe(Context c,JSONObject policy,JSONObject row){try{long now=System.currentTimeMillis();String type=row.optString("type");if(type.equals("heart_rate")){heart=row.isNull("value")||!row.has("value")?null:(float)row.optDouble("value");heartAt=row.optLong("observed_at_epoch_ms",now);}if(type.equals("light")){light=row.isNull("value")||!row.has("value")?null:(float)row.optDouble("value");lightAt=row.optLong("observed_at_epoch_ms",now);}JSONObject rule=policy.optJSONObject("context_reminder");if(rule==null||!rule.optBoolean("enabled")||heart==null||light==null||heart<=0||light<0||now<heartAt||now<lightAt||now-heartAt>900000||now-lightAt>900000||heart>=rule.optInt("heart",70)||light>=rule.optInt("lux",50))return;Calendar time=Calendar.getInstance();if(time.get(Calendar.HOUR_OF_DAY)*60+time.get(Calendar.MINUTE)<rule.optInt("hour",21)*60+rule.optInt("minute",30))return;String day=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(time.getTime());SharedPreferences p=c.getSharedPreferences("context-reminder",0);if(p.getString("last-day","").equals(day))return;Vibrator v=(Vibrator)c.getSystemService(Context.VIBRATOR_SERVICE);if(v!=null&&v.hasVibrator())v.vibrate(VibrationEffect.createWaveform(new long[]{0,90,130,90},-1));p.edit().putString("last-day",day).apply();}catch(Exception ignored){}}
}
